import{_ as e,o as d,c as a,a2 as s}from"./chunks/framework.CDU0sSpB.js";const k=JSON.parse('{"title":"Day08 · 通用执行内核与 native 30 题评测","description":"","frontmatter":{"title":"Day08 · 通用执行内核与 native 30 题评测","outline":false},"headers":[],"relativePath":"log/day-08.md","filePath":"log/day-08.md","lastUpdated":1794450028000}'),i={name:"log/day-08.md"};function o(r,t,c,l,h,n){return d(),a("div",null,[...t[0]||(t[0]=[s(`<p>2026-11-11 至 11-12，Hearth 把 <code>native</code> 从精简编码循环升级为通用执行内核，并用独立评测仓库对 30 个离线 case 做了第一轮完整测量。11-11 的 16 个计划项涉及 81 个文件（+7,156/−850）；11-12 在基线 <code>4617419</code> 之后又完成 91 个提交（19 个文件，+2,358/−17），主要用于评测结果归一化和最终修复。最终修复提交为 <code>eb32ad5</code>，文档随后补齐。</p><h2 id="通用执行内核" tabindex="-1">通用执行内核 <a class="header-anchor" href="#通用执行内核" aria-label="Permalink to &quot;通用执行内核&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方向</th><th>结果</th></tr></thead><tbody><tr><td>文件与命令</td><td>新增 glob/grep、文档读取、XLSX/CSV/DOCX 生成；<code>edit_file</code> 可预览差异，补丁先校验全部目标再原子写入，支持 move 和真实删除；Shell 完整输出写入任务内 <code>.hearth/shell</code> 日志，只回填尾部，超时会杀死整个进程树</td></tr><tr><td>上下文与稳定性</td><td>模型窗口默认 128K、最大输出默认 8K；按窗口预留 <code>max(16K, 15%)</code> 并保留约 20K 近期 Token，只在完整回合边界压缩，绝不拆散工具调用与结果；压缩后写检查点；纯文本不再算完成，连续未调用 <code>finish_task</code> 会失败；429/5xx/网络错误最多重试两次，相同工具参数循环会被提示并停止重复执行</td></tr><tr><td>技能与委派</td><td>提示词只注入技能索引，<code>load_skill</code> 校验内容哈希、任务权限和审计后返回正文，<code>read_skill_resource</code> 限制在技能包内；<code>delegate_task</code> 使用新上下文，只允许只读或隔离写，单层串行、每父任务最多两个、禁止 MCP 和自动合并，子代理用量计入父任务</td></tr><tr><td>项目与 Worktree</td><td>新增本地 Git 项目注册、路径与 Git 根校验、分支校验和设置页项目列表；项目任务使用 <code>hearth/&lt;task-id&gt;</code> 独立 Worktree，恢复时复用，成功或失败都保留，只有用户手动清理且工作区干净时才删除；GitHub 任务继续走 Codex</td></tr><tr><td>本地 MCP</td><td>仅支持 stdio，服务器命令、参数和加密环境值由设置页管理；启动探测、工具发现、超时和崩溃隔离形成闭环；工具统一命名为 <code>mcp__&lt;serverId&gt;__&lt;toolName&gt;</code>，调用前用 <code>ajv</code> 校验 JSON Schema，结果限长，输出、错误和 stderr 均脱敏，并检测跨服务器及内置工具名称冲突</td></tr><tr><td>搜索与审批</td><td>搜索默认关闭，仅支持 Tavily 与 SearXNG；公共网络能力仍受 DNS、重定向和私网地址拦截，每次抓取仍审批；每次 MCP 调用进入现有逐次工具审批，绑定服务器、工具名和参数摘要，只有完全权限模式自动放行并记录审计</td></tr></tbody></table><p>这一轮的边界同样明确：没有远程 MCP、OAuth、浏览器自动化搜索、图片/扫描件视觉理解、PPTX、LSP、格式化器、Shell 后台会话或自动 cherry-pick。工具数量增加不等于执行质量已经经过真实用户验收。</p><h2 id="native-30-题评测" tabindex="-1">Native 30 题评测 <a class="header-anchor" href="#native-30-题评测" aria-label="Permalink to &quot;Native 30 题评测&quot;">​</a></h2><p>评测使用 <code>hearthproject/hearth-eval</code> 的 30 个离线 case（8 个任务族均匀分布），仅运行 <code>native</code> 执行器，重复 1 次，自动评分和自动重试开启，并发 4。</p><table tabindex="0"><thead><tr><th>阶段</th><th style="text-align:right;">结果</th></tr></thead><tbody><tr><td>初始基线 <code>EXP-20261111051349-b71b80</code></td><td style="text-align:right;">0/30 通过；评测桥接的任务带有空 <code>permissions.tools</code>，工具全部被过滤</td></tr><tr><td>第一次完整 30 题 <code>EXP-20261111141538-011506</code></td><td style="text-align:right;">15/30 通过（50%），平均分 81.33</td></tr><tr><td>最好完整 30 题 <code>EXP-20261111145332-7a95ea</code></td><td style="text-align:right;"><strong>18/30 通过（60%）</strong>，平均分 88.89</td></tr><tr><td>最近完整 30 题 <code>EXP-20261112003215-b1172b</code></td><td style="text-align:right;">12/30 通过（40%），平均分 73.33</td></tr><tr><td>累计定向确认</td><td style="text-align:right;"><strong>19/30</strong> 个 case 曾达到 100 分</td></tr></tbody></table><p>最近完整实验受到 provider 慢响应、评分 JSON 截断和任务超时影响，而且早于最后四个归一化修复，因此不能直接等同于最终代码能力。累计 19/30 来自不同轮次和定向重跑，不是一次连续实验。最终提交 <code>eb32ad5</code> 还没有做不中断的完整 30 题复测；这是一条必须保留的验证边界。</p><p>修复集中在三类：评测桥接与运行时（恢复默认工具白名单、任务级审批模式、禁止评测任务移交、代码任务 Shell 权限、瞬态重试、机器可读 facts 门禁）；结果契约与归一化（阻塞计数、冲突标记、备用时间槽、下一页查询、扁平 metadata、必填字段、桌面移动/删除计数等）；Prompt 契约（合同测试、直接交付、恢复最终状态、回滚章节、回归检查等）。</p><h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h2><p>2026-11-12 在当前分支运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # 100 个测试文件、725 个测试全部通过</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # TypeScript 类型检查</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # Web 控制面</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # VitePress 文档站</span></span></code></pre></div><p><code>vitest.config.ts</code> 将单个测试超时提高到 20 秒，避免 Windows 上 Git、Worktree 和 MCP 探测测试被默认 5 秒超时误判。独立评测仓库当前有 11 个测试文件、41 个测试；<code>npm run typecheck:scenarios</code> 已补上 <code>turndown-plugin-gfm</code> 的模块声明并通过。</p><h2 id="关键提交" tabindex="-1">关键提交 <a class="header-anchor" href="#关键提交" aria-label="Permalink to &quot;关键提交&quot;">​</a></h2><table tabindex="0"><thead><tr><th>提交</th><th>修改</th></tr></thead><tbody><tr><td><code>0a26af5</code></td><td>增加 glob 与安全 grep</td></tr><tr><td><code>49d883d</code></td><td>文件编辑原子化并支持差异预览</td></tr><tr><td><code>cc83883</code></td><td>加固 Shell 执行与进程树超时</td></tr><tr><td><code>c7cd318</code></td><td>增加办公文件生成工具</td></tr><tr><td><code>bfc7478</code></td><td>增加联网研究工具</td></tr><tr><td><code>babb0c2</code></td><td>增加 Token 感知上下文压缩</td></tr><tr><td><code>58d0ccf</code></td><td>技能按需加载</td></tr><tr><td><code>96559e9</code> / <code>c659692</code></td><td>本地 Git 项目注册与隔离 Worktree</td></tr><tr><td><code>909431e</code></td><td>有界子代理</td></tr><tr><td><code>09741da</code> / <code>276a91f</code></td><td>本地 MCP 管理与绑定审批的工具调用</td></tr><tr><td><code>0df47a3</code> / <code>238b14b</code> / <code>cee1e02</code></td><td>评测任务工具白名单、任务级审批模式与禁止移交</td></tr><tr><td><code>05bb8de</code> / <code>4f992c4</code> / <code>6bb4479</code> / <code>eb32ad5</code></td><td>最后四个结果归一化修复</td></tr></tbody></table><p>评测报告与复现方式见<a href="/hearth-os/evaluation/">评测与结果</a>；阶段二至六的能力矩阵见<a href="/hearth-os/delivery/status.html">交付状态</a>。</p>`,16)])])}const b=e(i,[["render",o]]);export{k as __pageData,b as default};
